from typing import Any

from django.contrib.auth.models import Permission
from django.contrib.contenttypes.models import ContentType
from django.http import HttpResponse

# Generated by manage.py generate_test_cases.
from rest_framework.test import APIRequestFactory, force_authenticate

from bloomerp.models import FieldPolicy, Policy, RowPolicy
from bloomerp.models.application_field import ApplicationField
from bloomerp.models.definition import BloomerpModelConfig
from bloomerp.permissions.manager import ensure_model_permissions
from bloomerp.tests.base import (
    BloomerpAPIViewTestCase,
    ExpectedResult,
    RequestScenario,
)
from bloomerp.views.api.mutations import AssistantMutationCatalogView


class TestAssistantMutationCatalogView(BloomerpAPIViewTestCase):
    """Tests class `AssistantMutationCatalogView` from `bloomerp/views/api/mutations.py`."""

    view_name = "api_assistant_mutation_catalog"
    create_foreign_models = True

    def extendedSetup(self) -> None:
        """Configure the catalog fixture with its shared Django model identity."""
        self.CustomerModel.bloomerp_config = BloomerpModelConfig()
        self.resource = self.CustomerModel._meta.label

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover model-label catalog discovery, relationships, and access filtering."""
        return [
            RequestScenario(
                name="Catalog lists operations and writable field metadata",
                description=(
                    "UC: An administrator inspects one generated API resource.\n"
                    "Expected Result: The catalog describes object IDs, operations, and writable fields."
                ),
                user=self.admin_user,
                query_params={"model_label": self.resource, "page": 1, "page_size": 1},
                expected=ExpectedResult(
                    response_validators=self.catalog_metadata_is_complete
                ),
            ),
            RequestScenario(
                name="Catalog represents foreign keys as related resources",
                description=(
                    "UC: A mutation field points to another generated resource.\n"
                    "Expected Result: The catalog exposes the resource name without embedding choices."
                ),
                user=self.admin_user,
                query_params={"model_label": self.resource, "page_size": 1},
                expected=ExpectedResult(
                    response_validators=self.foreign_key_uses_resource
                ),
            ),
            RequestScenario(
                name="Catalog search filters generated resources",
                description=(
                    "UC: A user searches the mutation catalog by resource name.\n"
                    "Expected Result: Matching resources are returned."
                ),
                user=self.admin_user,
                query_params={"search": "customer", "page_size": 1},
                expected=ExpectedResult(
                    response_validators=self.search_returns_customer
                ),
            ),
            RequestScenario(
                name="Catalog pagination can return an empty later page",
                description=(
                    "UC: A user requests a page after the filtered results.\n"
                    "Expected Result: The page is empty and previous-page metadata is accurate."
                ),
                user=self.admin_user,
                query_params={"model_label": self.resource, "page": 2, "page_size": 1},
                expected=ExpectedResult(response_validators=self.second_page_is_empty),
            ),
            RequestScenario(
                name="Catalog applies operation-specific field permissions",
                description=(
                    "UC: A user can add and change only one model field.\n"
                    "Expected Result: Only those operations and that field appear in the catalog."
                ),
                user=self.normal_user,
                prepare=self.grant_first_name_write_access,
                expected=ExpectedResult(
                    response_validators=self.catalog_is_permission_scoped
                ),
            ),
            RequestScenario(
                name="Catalog hides resources without write permission",
                description=(
                    "UC: A user has no write access to a generated resource.\n"
                    "Expected Result: The filtered catalog contains no resource entry."
                ),
                user=self.normal_user,
                query_params={"model_label": self.resource},
                expected=ExpectedResult(response_validators=self.catalog_is_empty),
            ),
        ]

    def get_customer_resource(self, response: HttpResponse) -> dict[str, Any]:
        """Find the catalog entry by its canonical model label."""
        return next(
            item
            for item in response.json()["resources"]
            if item["model_label"] == self.resource
        )

    def catalog_metadata_is_complete(self, response: HttpResponse) -> bool:
        """Verify operation metadata and pagination describe the selected model."""
        payload = response.json()
        resource = self.get_customer_resource(response)
        create_fields = {
            field["name"]: field for field in resource["operations"]["create"]["fields"]
        }
        update_fields = {
            field["name"]: field for field in resource["operations"]["update"]["fields"]
        }
        return (
            payload["page"] == 1
            and payload["page_size"] == 1
            and payload["total_resources"] == 1
            and payload["total_pages"] == 1
            and not payload["has_next"]
            and not payload["has_previous"]
            and resource["object_id"]
            == {"field": "id", "type": "string", "format": "uuid"}
            and set(resource["operations"]) == {"create", "update", "delete"}
            and create_fields["first_name"]["required"]
            and not update_fields["first_name"]["required"]
            and create_fields["age"]["type"] == "integer"
            and not {"created_by", "updated_by", "datetime_created", "datetime_updated"}
            & set(create_fields)
        )

    def foreign_key_uses_resource(self, response: HttpResponse) -> bool:
        """Verify relations use the same model-label identity as catalog entries."""
        resource = self.get_customer_resource(response)
        country = next(
            field
            for field in resource["operations"]["create"]["fields"]
            if field["name"] == "country"
        )
        expected_resource = self.CountryModel._meta.label
        return (
            country.get("related_model_label") == expected_resource
            and "choices" not in country
        )

    def search_returns_customer(self, response: HttpResponse) -> bool:
        """Confirm display-name searches return canonical identities."""
        payload = response.json()
        return (
            payload["total_resources"] >= 1
            and bool(payload["resources"])
            and all(
                "customer" in item["model_label"].lower()
                for item in payload["resources"]
            )
        )

    @staticmethod
    def second_page_is_empty(response: HttpResponse) -> bool:
        """Verify pagination past the sole model yields an empty page."""
        payload = response.json()
        return (
            payload["resources"] == []
            and payload["total_resources"] == 1
            and payload["has_previous"]
            and not payload["has_next"]
        )

    def grant_first_name_write_access(self, _scenario: RequestScenario) -> None:
        """Grant the ordinary actor write access only to the first-name field."""
        content_type = ContentType.objects.get_for_model(self.CustomerModel)
        first_name = ApplicationField.get_by_field(self.CustomerModel, "first_name")
        field_policy = FieldPolicy.objects.create(
            content_type=content_type,
            name="Mutation catalog fields",
            rule={str(first_name.pk): ["add_customer", "change_customer"]},
        )
        row_policy = RowPolicy.objects.create(
            content_type=content_type,
            name="Mutation catalog rows",
        )
        policy = Policy.objects.create(
            name="Mutation catalog policy",
            row_policy=row_policy,
            field_policy=field_policy,
        )
        policy.assign_user(self.normal_user)
        ensure_model_permissions(self.CustomerModel)
        self.normal_user.user_permissions.add(
            *Permission.objects.filter(
                content_type=content_type,
                codename__in=["add_customer", "change_customer"],
            )
        )

    def catalog_is_permission_scoped(self, response: HttpResponse) -> bool:
        """Verify catalog operations contain only permitted writable fields."""
        resource = self.get_customer_resource(response)
        return (
            set(resource["operations"]) == {"create", "update"}
            and [field["name"] for field in resource["operations"]["create"]["fields"]]
            == ["first_name"]
            and [field["name"] for field in resource["operations"]["update"]["fields"]]
            == ["first_name"]
        )

    def catalog_is_empty(self, response: HttpResponse) -> bool:
        """Ensure unauthorized models are absent from catalog results."""
        payload = response.json()
        return (
            payload["total_resources"] == 0
            and payload["total_pages"] == 0
            and self.resource
            not in [item["model_label"] for item in payload["resources"]]
        )

    def test_catalog_uses_shared_model_labels(self) -> None:
        """Expose exact model and relation labels without requiring resource-name inference."""
        request = APIRequestFactory().get(
            "/api/mutations/catalog/",
            {"model_label": self.CustomerModel._meta.label.lower()},
        )
        force_authenticate(request, user=self.admin_user)
        response = AssistantMutationCatalogView.as_view()(request)
        self.assertEqual(response.status_code, 200)
        self.assertEqual(response.data["total_resources"], 1)
        item = response.data["resources"][0]
        self.assertEqual(item["model_label"], self.CustomerModel._meta.label)
        country = next(
            field
            for field in item["operations"]["create"]["fields"]
            if field["name"] == "country"
        )
        self.assertEqual(country["related_model_label"], self.CountryModel._meta.label)
